//! Transactions and the page-key lock queue (core): the store methods behind transaction,
//! transactionDirect and lockPageKeys. The wrapper (`src/core/rust-engine.ts`) builds a second
//! `Brain` on its own one-thread pool (the transaction executor), binds it to a transaction on the
//! engine's brain with `beginTransaction`, runs the callback's calls on it, and ends it with
//! `commitTransaction` or `rollbackTransaction`. Contract: `rust/docs/store/transactions.md`.
//!
//! Built by the core store work; other families do not edit this file.

use gbrain_store::StoreError;
use gbrain_store::transactions::{PageKeyHint, TxnMode, TxnOptions};
use napi::Env;
use napi::bindgen_prelude::Object;
use napi_derive::napi;
use serde_json::Value;

use crate::store_binding::{Brain, instant_at, required};

/// The options of `beginTransaction` (multi-user mode only; absent = today's transaction).
#[napi(object)]
pub struct BeginTransactionOptions {
    /// `'optimistic'` runs the transaction optimistically (store `TxnMode::Optimistic`); anything
    /// else, or absent, serialized.
    pub mode: Option<String>,
    /// Absolute deadline, milliseconds since the Unix epoch.
    pub deadline_at_ms: Option<f64>,
    /// Keys (lowercase hex) an earlier run lost a conflict on: the transaction queues for them first.
    pub retry_keys: Option<Vec<String>>,
    /// The single-flight age of an earlier run (`transactionAge()`), kept by a rerun.
    pub age: Option<f64>,
}

/// Lowercase hex to bytes; `invalid_argument` for anything else.
fn hex_key(hex: &str) -> Result<Vec<u8>, StoreError> {
    if !hex.len().is_multiple_of(2) || hex.is_empty() {
        return Err(StoreError::invalid("a retry key is not hex"));
    }
    (0..hex.len())
        .step_by(2)
        .map(|i| {
            u8::from_str_radix(&hex[i..i + 2], 16)
                .map_err(|_| StoreError::invalid("a retry key is not hex"))
        })
        .collect()
}

#[napi]
impl Brain {
    /// `beginTransaction(outer, readOnly?)`, on a closed handle: waits for the writer of `outer`'s
    /// brain, opens the write transaction and makes this handle run on it. Resolves `null`.
    /// Rejects `store_closed` when `outer` is closed and `invalid_state` when this handle is open.
    #[napi]
    pub fn begin_transaction<'env>(
        &self,
        env: &'env Env,
        outer: &Brain,
        read_only: Option<bool>,
        options: Option<BeginTransactionOptions>,
    ) -> napi::Result<Object<'env>> {
        let store = outer.current();
        let read_only = read_only.unwrap_or(false);
        let options = options.map(|o| {
            let retry_keys = o.retry_keys.unwrap_or_default();
            (
                TxnOptions {
                    mode: if o.mode.as_deref() == Some("optimistic") {
                        TxnMode::Optimistic
                    } else {
                        TxnMode::Serialized
                    },
                    deadline: o.deadline_at_ms.map(instant_at),
                    origin: None,
                    read_only,
                    retry_keys: Vec::new(),
                    age: o
                        .age
                        .filter(|a| a.is_finite() && *a >= 0.0)
                        .map(|a| a as u64),
                },
                retry_keys,
            )
        });
        self.bind(env, move || {
            let store = store.ok_or_else(|| {
                StoreError::new(gbrain_store::error::STORE_CLOSED, "the brain is not open")
            })?;
            let options = match options {
                None => None,
                Some((mut options, keys)) => {
                    options.retry_keys =
                        keys.iter().map(|k| hex_key(k)).collect::<Result<_, _>>()?;
                    Some(options)
                }
            };
            match options {
                None => store.begin_transaction(read_only),
                Some(options) => store.begin_bound(options),
            }
        })
    }

    /// `transactionAge()`: the bound transaction's single-flight age, for the next run's `age` option.
    #[napi]
    pub fn transaction_age<'env>(&self, env: &'env Env) -> napi::Result<Object<'env>> {
        self.run(env, |s| s.transaction_age())
    }

    /// `transactionConflicted()`: true when the bound optimistic transaction met a
    /// `write_conflict` (the wrapper runs the callback again). False otherwise.
    #[napi]
    pub fn transaction_conflicted<'env>(&self, env: &'env Env) -> napi::Result<Object<'env>> {
        self.run(env, |s| Ok(s.transaction_conflicted()))
    }

    /// `savepoint()`: opens a savepoint and resolves its depth.
    #[napi]
    pub fn savepoint<'env>(&self, env: &'env Env) -> napi::Result<Object<'env>> {
        self.run(env, |s| s.savepoint())
    }

    /// `releaseSavepoint(depth)`: keeps the innermost savepoint's writes. Resolves `null`.
    #[napi]
    pub fn release_savepoint<'env>(
        &self,
        env: &'env Env,
        depth: u32,
    ) -> napi::Result<Object<'env>> {
        self.run(env, move |s| s.release_savepoint(depth))
    }

    /// `rollbackSavepoint(depth)`: drops the innermost savepoint's writes. Resolves `null`.
    #[napi]
    pub fn rollback_savepoint<'env>(
        &self,
        env: &'env Env,
        depth: u32,
    ) -> napi::Result<Object<'env>> {
        self.run(env, move |s| s.rollback_savepoint(depth))
    }

    /// `setTransactionReadOnly()`: `SET TRANSACTION READ ONLY`; every later write in the
    /// transaction rejects `read_only_transaction`. Resolves `null`.
    #[napi]
    pub fn set_transaction_read_only<'env>(&self, env: &'env Env) -> napi::Result<Object<'env>> {
        self.run(env, |s| s.set_transaction_read_only())
    }

    /// `commitTransaction()`: commits and resolves the commit sequence.
    #[napi]
    pub fn commit_transaction<'env>(&self, env: &'env Env) -> napi::Result<Object<'env>> {
        self.run(env, |s| s.commit_transaction())
    }

    /// `rollbackTransaction()`: rolls back (a no-op once ended). Resolves `null`.
    #[napi]
    pub fn rollback_transaction<'env>(&self, env: &'env Env) -> napi::Result<Object<'env>> {
        self.run(env, |s| s.rollback_transaction())
    }

    /// `holdPageKeys(keys, hinted)`: `lockPageKeys` inside the transaction. Resolves every held
    /// key as `[sourceId, slug]`, sorted.
    #[napi]
    pub fn hold_page_keys<'env>(
        &self,
        env: &'env Env,
        keys: Value,
        hinted: bool,
    ) -> napi::Result<Object<'env>> {
        self.run(env, move |s| {
            let keys: Vec<PageKeyHint> = required(keys, "holdPageKeys keys")?;
            s.hold_page_keys(&keys, hinted)
        })
    }
}
